sys_script_include.script:
var DateDuplicate = Class.create();
DateDuplicate.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkDuplicates: function() {
		// pega os parametros
        var date = this.getParameter("sysparm_date");  
        var training = this.getParameter("sysparm_trainingSysId");
		// cria objeto para a tabela de schedule
        var grTraining = new GlideRecord("x_1593191_cooknow_training_schedule");

		// busca os registros com o mesmo nome e mesma data e faz a consulta no banco de dados
        grTraining.addQuery("training", training);
        grTraining.addQuery("date", date);  
        grTraining.query();

		// verifica se encontrou algum registro com o mesmo nome e data
        if (grTraining.next()) {
            return true;  // se sim
        } else {
            return false;   // se não
        }
    },
    type: 'DateDuplicate'
});
